// ?getPreferredMap@LANPreferences@@QAE?AVAsciiString@@XZ
// partial score=0.75 date=2026-09-05
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc
// LANPreferences::getPreferredMap at retail RVA 0x00086A20, 377B.
// Same shape as the ZH source (reference/.../LanLobbyMenu.cpp:160), but the
// retail callee list has no isValidMap call, so BFME dropped that guard:
// only the "not found" and "empty after decode" branches fall back to
// getDefaultMap(TRUE). Model follows the minimal-shim style proven for
// Code/GameEngine/Source/Common/Gen_0009E3D0_SkirmishPreferences_getPreferredColor.cpp,
// including its nested-scope key-temp pattern so the key's destructor call
// sits where retail's does (right after find(), before the it/end() compare).
//
// STILL BLOCKED on the EH-state-byte order around the "Map" key temp's
// construct/find/destruct sequence (349/377 bytes, first divergence at +0x4e):
// retail writes the EH state byte for the *next* protected region only AFTER
// the key's destructor call; every source shape tried here (this nested block,
// a single-statement `find(AsciiString("Map"))`, and swapping in the real
// WWLib StringBase<char>-backed AsciiString from reference/shims/
// campaignmanagerascii/Common/AsciiString.h with PreRTS.h) either reproduces
// this same transposition or regresses further (the StringBase-backed swap
// moved the first divergence back to +0x19, in the AsciiString ret; default
// construction, for reasons not run down -- likely an unrelated register
// pressure change from string_base.h's larger surface, not the EH lever).
// Left as the best known candidate for this session; see re_attempts.log
// blocker=PREFMAP_KEYTEMP_EH_ORDER for the full family note (0x0009E470,
// 0x0009E830 share this same wall).

class AsciiStringData
{
public:
	char m_pad[8];
	char m_text[1];
};

class AsciiString
{
public:
	AsciiString() : m_data(0) {}
	AsciiString(const char *text);
	AsciiString(const AsciiString &other);
	~AsciiString();

	AsciiString &operator=(const AsciiString &other);

	bool isEmpty() const
	{
		return m_data == 0;
	}

	void trim();

	const char *str() const
	{
		return m_data ? m_data->m_text : "";
	}

private:
	AsciiStringData *m_data;
};

AsciiString QuotedPrintableToAsciiString(AsciiString original);
AsciiString getDefaultMap(bool useIfNotFound);

struct PreferenceNode
{
	char m_pad[0x14];
	AsciiString m_value;
};

class PreferenceMap
{
public:
	PreferenceNode *find(const AsciiString &) const;
	PreferenceNode *end() const
	{
		return m_end;
	}

private:
	PreferenceNode *m_end;
};

class UserPreferences : public PreferenceMap
{
public:
	virtual ~UserPreferences();
};

class LANPreferences : public UserPreferences
{
public:
	AsciiString getPreferredMap(void);
};

// ?getPreferredMap@LANPreferences@@QAE?AVAsciiString@@XZ
AsciiString LANPreferences::getPreferredMap(void)
{
	AsciiString ret;
	PreferenceNode *it;
	{
		AsciiString key("Map");
		it = find(key);
	}

	if (it == end())
	{
		ret = getDefaultMap(true);
		return ret;
	}

	ret = QuotedPrintableToAsciiString(it->m_value);
	ret.trim();
	if (ret.isEmpty())
	{
		ret = getDefaultMap(true);
		return ret;
	}

	return ret;
}
